P=Path(__file__).resolve().parent
R=json.loads((P/'results.json').read_text());concepts=R['concepts'];byconcept={c['concept']:c for c in concepts}
BLUE='#4655df';TEAL='#06786f';INK='#17233a';GRAY='#667085';PALETTE=[TEAL,BLUE,'#9b4ca8','#bf6f1c']
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':11,'axes.spines.top':False,'axes.spines.right':False,'axes.labelcolor':INK,'text.color':INK,'axes.edgecolor':'#d5dbe7','xtick.color':GRAY,'ytick.color':INK,'figure.facecolor':'white','axes.facecolor':'white','savefig.facecolor':'white'})
