words=[x for x in R['lexical'] if x['term'] in ['agent','model','data','token','tool','code','human','cost','software','access','evaluation','gpu']]
words=sorted(words,key=lambda x:x['mentions'],reverse=True)[:12];ys=np.arange(len(words))
axes[0].barh(ys,[x['mentions'] for x in words],color=BLUE,height=.63);axes[0].set_yticks(ys,[x['term'] for x in words]);axes[0].invert_yaxis();axes[0].set_xlabel('Normalized token mentions');axes[0].set_title('Common technical vocabulary',loc='left',fontweight='bold',pad=16)
for i,x in enumerate(words):axes[0].text(x['mentions']+12,i,str(x['mentions']),va='center',fontsize=10)
axes[0].set_xlim(0,max(x['mentions'] for x in words)*1.15)
sel=concepts[:16];ys=np.arange(len(sel));axes[1].barh(ys,[x['talks'] for x in sel],color=TEAL,height=.63);axes[1].set_yticks(ys,[x['concept'] for x in sel]);axes[1].invert_yaxis();axes[1].set_xlim(0,49);axes[1].set_xlabel('Talks with at least two matching transcript segments');axes[1].set_title('Breadth across 47 talk recordings',loc='left',fontweight='bold',pad=16)
for i,x in enumerate(sel):axes[1].text(x['talks']+.5,i,f"{x['talks']}/47",va='center',fontsize=10)
fig.suptitle('AI Engineer NYC: what the two livestreams repeatedly discuss',fontsize=19,fontweight='bold',x=.06,ha='left');fig.text(.06,.015,'134,250 spoken words · 47 distinct talk recordings · Categories overlap. Mentions measure presence, not importance or agreement.',fontsize=10,color=GRAY)
fig.tight_layout(rect=[.03,.05,1,.93],w_pad=4);fig.savefig(P/'topic-overview.png',dpi=180);plt.close(fig)
